public void close(String tenantId, String routeId) {
    RouteState state = routes.remove(key(tenantId, routeId));
    if (state != null) state.client().close("route_closed");
}

public void unregisterHost(String tenantId, String hostId) {
    presence.remove(key(tenantId, hostId));
    routes.entrySet().removeIf(entry -> {
        RouteState state = entry.getValue();
        if (!state.tenantId().equals(tenantId) || !state.route().hostId().equals(hostId)) return false;
        state.client().close("host_offline");
        return true;
    });
}

public Optional<RelayMetadataStore.Host> host(String tenantId, String hostId) {
    return store.host(tenantId, hostId);
}
